(function(){'use strict';var API_URL='/api/chat';var STORAGE_KEY='agnes_chat_history';var MAX_HISTORY=30;var FIRST_BYTE_TIMEOUT=15000;var IDLE_TIMEOUT=30000;var QUICK_QUESTIONS={plan:['帮我规划3天行程','2天家庭游怎么安排','预算500元怎么玩'],chat:['北戴河有什么好玩的','山海关值得去吗','秦皇岛哪里吃海鲜']};var state={isOpen:false,mode:'plan',messages:[],isStreaming:false,abortController:null};var dom={};function init(){if(document.querySelector('.agnes-chat-widget'))return;loadHistory();var container=document.createElement('div');container.className='agnes-chat-widget';container.innerHTML=buildHTML();document.body.appendChild(container);cacheDom();dom.tabs.forEach(function(tab){tab.classList.toggle('agnes-active',tab.getAttribute('data-mode')===state.mode);});bindEvents();renderMessages();renderQuickQuestions();}function buildHTML(){return [ '<!--浮动按钮-->','<button class="agnes-chat-fab" aria-label="打开AI旅游助手" title="秦皇岛AI旅游助手">','<svg viewBox="0 0 24 24"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>','</button>','<!--聊天窗口-->','<div class="agnes-chat-window" role="dialog" aria-label="秦皇岛AI旅游助手">','<div class="agnes-chat-header">','<div class="agnes-chat-header-info">','<div class="agnes-chat-header-icon">','<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg>','</div>','<div class="agnes-chat-header-text">','<h3>秦皇岛AI旅游助手</h3>','<span><i class="agnes-status-dot"></i>在线 · 随时为你服务</span>','</div>','</div>','<button class="agnes-chat-close" aria-label="关闭" title="关闭">','<svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>','</button>','</div>','<div class="agnes-chat-tabs">','<button class="agnes-chat-tab agnes-active" data-mode="plan">行程规划</button>','<button class="agnes-chat-tab" data-mode="chat">景点问答</button>','</div>','<div class="agnes-chat-messages"></div>','<div class="agnes-quick-questions"></div>','<div class="agnes-chat-input-area">','<textarea class="agnes-chat-input" placeholder="输入你的问题..." rows="1" aria-label="消息输入框"></textarea>','<button class="agnes-chat-send" aria-label="发送" title="发送">','<svg viewBox="0 0 24 24"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>','</button>','</div>','</div>' ].join('\n');}function cacheDom(){var root=document.querySelector('.agnes-chat-widget');dom.fab=root.querySelector('.agnes-chat-fab');dom.window=root.querySelector('.agnes-chat-window');dom.closeBtn=root.querySelector('.agnes-chat-close');dom.tabs=root.querySelectorAll('.agnes-chat-tab');dom.messages=root.querySelector('.agnes-chat-messages');dom.quickQuestions=root.querySelector('.agnes-quick-questions');dom.input=root.querySelector('.agnes-chat-input');dom.sendBtn=root.querySelector('.agnes-chat-send');}function bindEvents(){dom.fab.addEventListener('click',toggleWindow);dom.closeBtn.addEventListener('click',closeWindow);dom.tabs.forEach(function(tab){tab.addEventListener('click',function(){var newMode=tab.getAttribute('data-mode');if(newMode===state.mode)return;switchMode(newMode);});});dom.sendBtn.addEventListener('click',handleSend);dom.input.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();handleSend();}});dom.input.addEventListener('input',autoResizeInput);document.addEventListener('keydown',function(e){if(e.key==='Escape'&&state.isOpen){closeWindow();}});}function toggleWindow(){if(state.isOpen){closeWindow();}else{openWindow();}}function openWindow(){state.isOpen=true;dom.fab.classList.add('agnes-hidden','agnes-opened');dom.window.classList.add('agnes-visible');setTimeout(function(){dom.input.focus();scrollToBottom();},300);}function closeWindow(){state.isOpen=false;dom.fab.classList.remove('agnes-hidden');dom.window.classList.remove('agnes-visible');dom.input.blur();}function switchMode(newMode){state.mode=newMode;dom.tabs.forEach(function(tab){tab.classList.toggle('agnes-active',tab.getAttribute('data-mode')===newMode);});renderQuickQuestions();}function renderMessages(){dom.messages.innerHTML='';if(state.messages.length===0){var welcome=document.createElement('div');welcome.className='agnes-chat-welcome';welcome.innerHTML=[ '<div class="agnes-chat-welcome-icon">','<svg viewBox="0 0 24 24"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>','</div>','<h4>你好！我是秦皇岛AI旅游助手 👋</h4>','<p>我可以帮你规划行程、推荐景点和美食<br>选择上方模式，开始聊天吧！</p>' ].join('');dom.messages.appendChild(welcome);return;}state.messages.forEach(function(msg){dom.messages.appendChild(createMessageEl(msg));});scrollToBottom();}function createMessageEl(msg){var wrapper=document.createElement('div');wrapper.className='agnes-msg agnes-msg-'+msg.role;if(msg.role==='assistant'){var avatar=document.createElement('div');avatar.className='agnes-msg-ai-avatar';avatar.innerHTML=[ '<div class="agnes-msg-ai-avatar-icon">','<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg>','</div>','<span>AI助手</span>' ].join('');wrapper.appendChild(avatar);}var bubble=document.createElement('div');bubble.className='agnes-msg-bubble agnes-md';bubble.innerHTML=renderMarkdown(msg.content);wrapper.appendChild(bubble);return wrapper;}function renderQuickQuestions(){var questions=QUICK_QUESTIONS[state.mode]||QUICK_QUESTIONS.chat;dom.quickQuestions.innerHTML='';questions.forEach(function(q){var btn=document.createElement('button');btn.className='agnes-quick-q';btn.textContent=q;btn.addEventListener('click',function(){dom.input.value=q;handleSend();});dom.quickQuestions.appendChild(btn);});}function handleSend(){var text=dom.input.value.trim();if(!text||state.isStreaming)return;var userMsg={role:'user',content:text,timestamp:Date.now()};state.messages.push(userMsg);saveHistory();dom.input.value='';autoResizeInput();renderMessages();var aiMsg={role:'assistant',content:'',timestamp:Date.now()};state.messages.push(aiMsg);showTypingIndicator();streamChat(text);}var firstByteTimer=null;var idleTimer=null;function clearTimers(){if(firstByteTimer){clearTimeout(firstByteTimer);firstByteTimer=null;}if(idleTimer){clearTimeout(idleTimer);idleTimer=null;}}function resetIdleTimer(){if(idleTimer)clearTimeout(idleTimer);idleTimer=setTimeout(function(){if(state.abortController){state.abortController.abort();}showTimeoutError('连接超时，AI 响应时间过长，请重试或换个简短的问题');},IDLE_TIMEOUT);}function showTimeoutError(message){removeTypingIndicator();if(state.messages.length>0&&state.messages[state.messages.length-1].content===''){state.messages.pop();}showError(message);finishStreaming();renderMessages();}function streamChat(userText){state.isStreaming=true;updateSendButton();clearTimers();var apiMessages=state.messages .filter(function(m){return m.content.trim()!=='';}).map(function(m){return{role:m.role,content:m.content};});if(typeof AbortController!=='undefined'){state.abortController=new AbortController();}firstByteTimer=setTimeout(function(){var typing=document.getElementById('agnes-typing-wrapper');if(typing){var hint=document.createElement('div');hint.className='agnes-timeout-hint';hint.style.cssText='text-align:center;color:#999;font-size:12px;margin-top:8px;';hint.textContent='AI 正在思考中，网络可能较慢，请稍候...';typing.appendChild(hint);}},8000);var hardTimeout=setTimeout(function(){if(state.abortController){state.abortController.abort();}showTimeoutError('请求超时，请检查网络后重试');},FIRST_BYTE_TIMEOUT);fetch(API_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:apiMessages,mode:state.mode}),signal:state.abortController ? state.abortController.signal:undefined}).then(function(response){clearTimeout(hardTimeout);if(!response.ok){return response.json().then(function(err){throw new Error(err.message||'请求失败('+response.status+')');}).catch(function(){throw new Error('请求失败('+response.status+')');});}if(!response.body){throw new Error('浏览器不支持流式响应');}removeTypingIndicator();startStreamingRender();clearTimeout(firstByteTimer);resetIdleTimer();return readSSEStream(response.body);}).then(function(){clearTimers();finishStreaming();}).catch(function(err){clearTimers();clearTimeout(hardTimeout);removeTypingIndicator();if(err.name==='AbortError'){if(state.messages.length>0&&state.messages[state.messages.length-1].content===''){state.messages.pop();}}else{showError(err.message||'网络错误，请稍后重试');if(state.messages.length>0&&state.messages[state.messages.length-1].content===''){state.messages.pop();}}finishStreaming();renderMessages();});}function readSSEStream(stream){var reader=stream.getReader();var decoder=new TextDecoder('utf-8');var buffer='';var aiMsgIndex=state.messages.length-1;function processBuffer(){var lines=buffer.split('\n');buffer=lines.pop()||'';for(var i=0;i<lines.length;i++){var line=lines[i].trim();if(!line||line.startsWith(':'))continue;if(!line.startsWith('data:'))continue;var data=line.slice(5).trim();if(data==='[DONE]'){return true;}try{var parsed=JSON.parse(data);var delta=parsed.choices&&parsed.choices[0]&&parsed.choices[0].delta;if(delta&&delta.content){state.messages[aiMsgIndex].content+=delta.content;updateStreamingBubble(state.messages[aiMsgIndex].content);resetIdleTimer();}}catch(e){}}return false;}function pump(){return reader.read().then(function(result){if(result.done){if(buffer.trim()){processBuffer();}return;}buffer+=decoder.decode(result.value,{stream:true});if(processBuffer()){return;}return pump();});}return pump();}var streamingBubble=null;function startStreamingRender(){var welcome=dom.messages.querySelector('.agnes-chat-welcome');if(welcome)dom.messages.innerHTML='';var msgEl=createMessageEl({role:'assistant',content:''});dom.messages.appendChild(msgEl);streamingBubble=msgEl.querySelector('.agnes-msg-bubble');scrollToBottom();}function updateStreamingBubble(content){if(!streamingBubble)return;streamingBubble.innerHTML=renderMarkdown(content);scrollToBottom();}function finishStreaming(){state.isStreaming=false;state.abortController=null;streamingBubble=null;updateSendButton();saveHistory();}function showTypingIndicator(){var welcome=dom.messages.querySelector('.agnes-chat-welcome');if(welcome)welcome.remove();var typing=document.createElement('div');typing.className='agnes-msg agnes-msg-ai';typing.id='agnes-typing-wrapper';var avatar=document.createElement('div');avatar.className='agnes-msg-ai-avatar';avatar.innerHTML=[ '<div class="agnes-msg-ai-avatar-icon">','<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg>','</div>','<span>AI助手</span>' ].join('');var bubble=document.createElement('div');bubble.className='agnes-msg-bubble';bubble.style.padding='0';bubble.innerHTML='<div class="agnes-typing"><span class="agnes-typing-dot"></span><span class="agnes-typing-dot"></span><span class="agnes-typing-dot"></span></div>';typing.appendChild(avatar);typing.appendChild(bubble);dom.messages.appendChild(typing);scrollToBottom();}function removeTypingIndicator(){var typing=document.getElementById('agnes-typing-wrapper');if(typing)typing.remove();}function showError(message){var errEl=document.createElement('div');errEl.className='agnes-msg-error';errEl.textContent='⚠ '+message;dom.messages.appendChild(errEl);scrollToBottom();}function updateSendButton(){dom.sendBtn.disabled=state.isStreaming;dom.input.disabled=state.isStreaming;if(state.isStreaming){dom.input.placeholder='AI 正在回复...';}else{dom.input.placeholder='输入你的问题...';}}function scrollToBottom(){requestAnimationFrame(function(){dom.messages.scrollTop=dom.messages.scrollHeight;});}function autoResizeInput(){dom.input.style.height='auto';dom.input.style.height=Math.min(dom.input.scrollHeight,100)+'px';}function renderMarkdown(text){if(!text)return '';var html=escapeHtml(text);html=html.replace(/```(\w*)\n?([\s\S]*?)```/g,function(match,lang,code){return '<pre><code>'+code.trim()+'</code></pre>';});html=html.replace(/^###\s+(.+)$/gm,'<h3>$1</h3>');html=html.replace(/^##\s+(.+)$/gm,'<h2>$1</h2>');html=html.replace(/^#\s+(.+)$/gm,'<h1>$1</h1>');html=html.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');html=html.replace(/\*([^*\n]+)\*/g,'<em>$1</em>');html=html.replace(/`([^`]+)`/g,'<code>$1</code>');html=html.replace(/^[\-\*]\s+(.+)$/gm,'<li data-ul>$1</li>');html=html.replace(/(<li data-ul>[\s\S]*?<\/li>)(?!\s*<li data-ul>)/g,function(match){return '<ul>'+match.replace(/data-ul/g,'')+'</ul>';});html=html.replace(/^\d+\.\s+(.+)$/gm,'<li data-ol>$1</li>');html=html.replace(/(<li data-ol>[\s\S]*?<\/li>)(?!\s*<li data-ol>)/g,function(match){return '<ol>'+match.replace(/data-ol/g,'')+'</ol>';});html=html.replace(/^(?!<[hupol])(.+)$/gm,function(match,line){return line.trim()? '<p>'+line+'</p>':'';});return html;}function escapeHtml(text){var div=document.createElement('div');div.textContent=text;return div.innerHTML;}function saveHistory(){try{var toSave=state.messages.slice(-MAX_HISTORY);localStorage.setItem(STORAGE_KEY,JSON.stringify({mode:state.mode,messages:toSave,savedAt:Date.now()}));}catch(e){}}function loadHistory(){try{var raw=localStorage.getItem(STORAGE_KEY);if(!raw)return;var data=JSON.parse(raw);if(data&&Array.isArray(data.messages)&&data.messages.length>0){state.messages=data.messages;state.mode=data.mode||'plan';}}catch(e){}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();